Here is the commit message:
perf: Make sure to use pmu_ctx->pmu for groups

Oliver reported that x86_pmu_del() ended up doing an out-of-bound memory access
when group_sched_in() fails and needs to roll back.

This *should* be handled by the transaction callbacks, but he found that when
the group leader is a software event, the transaction handlers of the wrong PMU
are used. Despite the move_group case in perf_event_open() and group_sched_in()
using pmu_ctx->pmu.

Turns out, inherit uses event->pmu to clone the events, effectively undoing the
move_group case for all inherited contexts. Fix this by also making inherit use
pmu_ctx->pmu, ensuring all inherited counters end up in the same pmu context.

Similarly, __perf_event_read() should use equally use pmu_ctx->pmu for the
group case.

Fixes: bd2756811766 ("perf: Rewrite core context handling")
Reported-by: Oliver Rosenberg <olrose55@gmail.com>
Signed-off-by: Peter Zijlstra (Intel) <peterz@infradead.org>
Reviewed-by: Ian Rogers <irogers@google.com>
Link: https://patch.msgid.link/20260309133713.GB606826@noisy.programming.kicks-ass.net

Here is the root cause:
The bug occurs because `inherit_event()` used `child_event->pmu` instead of `parent_event->pmu_ctx->pmu` when creating the child's PMU context. This undoes the `move_group` logic from `perf_event_open()`, causing inherited events to be placed in the wrong PMU context. When `group_sched_in()` fails and rolls back, the incorrect PMU's transaction callbacks are invoked, leading to an out-of-bounds memory access in `x86_pmu_del()`. Additionally, `__perf_event_read()` used `event->pmu` instead of `event->pmu_ctx->pmu` for group reads, further propagating the mismatch.

Here is the patch:
  */
 static void __perf_event_read(void *info)
 {
 	struct perf_read_data *data = info;
 	struct perf_event *sub, *event = data->event;
 	struct perf_event_context *ctx = event->ctx;
 	struct perf_cpu_context *cpuctx = this_cpu_ptr(&perf_cpu_context);
-	struct pmu *pmu = event->pmu;
+	struct pmu *pmu;

 	/*
 	 * If this is a task context, we need to check whether it is
 	 * the current task context of this cpu.  If not it has been
 	 * scheduled out before the smp call arrived.  In that case
 	 * event->count would have been updated to a recent sample
 	 * when the event was scheduled out.
 	 */
 	if (ctx->task && cpuctx->task_ctx != ctx)
 		return;

-	raw_spin_lock(&ctx->lock);
+	guard(raw_spinlock)(&ctx->lock);
 	ctx_time_update_event(ctx, event);

 	perf_event_update_time(event);
 	if (data->group)
 		perf_event_update_sibling_time(event);

 	if (event->state != PERF_EVENT_STATE_ACTIVE)
-		goto unlock;
+		return;

 	if (!data->group) {
-		pmu->read(event);
+		perf_pmu_read(event);
 		data->ret = 0;
-		goto unlock;
+		return;
 	}

+	pmu = event->pmu_ctx->pmu;
 	pmu->start_txn(pmu, PERF_PMU_TXN_READ);

-	pmu->read(event);
-
+	perf_pmu_read(event);
 	for_each_sibling_event(sub, event)
 		perf_pmu_read(sub);

 	data->ret = pmu->commit_txn(pmu);
-
-unlock:
-	raw_spin_unlock(&ctx->lock);
 }

  */
 static struct perf_event *
 inherit_event(struct perf_event *parent_event,
 	      struct task_struct *parent,
 	      struct perf_event_context *parent_ctx,
 	      struct task_struct *child,
 	      struct perf_event *group_leader,
 	      struct perf_event_context *child_ctx)
 {
 	enum perf_event_state parent_state = parent_event->state;
 	struct perf_event_pmu_context *pmu_ctx;
 	struct perf_event *child_event;
 	unsigned long flags;

 	/*
 	 * Instead of creating recursive hierarchies of events,
 	 * we link inherited events back to the original parent,
 	 * which has a filp for sure, which we use as the reference
 	 * count:
 	 */
 	if (parent_event->parent)
 		parent_event = parent_event->parent;

 	if (parent_event->state <= PERF_EVENT_STATE_REVOKED)
 		return NULL;

 	/*
 	 * Event creation should be under SRCU, see perf_pmu_unregister().
 	 */
 	guard(srcu)(&pmus_srcu);

 	child_event = perf_event_alloc(&parent_event->attr,
 					   parent_event->cpu,
 					   child,
 					   group_leader, parent_event,
 					   NULL, NULL, -1);
 	if (IS_ERR(child_event))
 		return child_event;

 	get_ctx(child_ctx);
 	child_event->ctx = child_ctx;

-	pmu_ctx = find_get_pmu_context(child_event->pmu, child_ctx, child_event);
+	pmu_ctx = find_get_pmu_context(parent_event->pmu_ctx->pmu, child_ctx, child_event);
 	if (IS_ERR(pmu_ctx)) {
 		free_event(child_event);
 		return ERR_CAST(pmu_ctx);
 	}
 	child_event->pmu_ctx = pmu_ctx;

 	/*
 	 * is_orphaned_event() and list_add_tail(&parent_event->child_list)
 	 * must be under the same lock in order to serialize against
 	 * perf_event_release_kernel(), such that either we must observe
 	 * is_orphaned_event() or they will observe us on the child_list.
 	 */
 	mutex_lock(&parent_event->child_mutex);
 	if (is_orphaned_event(parent_event) ||
 	    !atomic_long_inc_not_zero(&parent_event->refcount)) {
 		mutex_unlock(&parent_event->child_mutex);
 		free_event(child_event);
 		return NULL;
 	}

 	/*
 	 * Make the child state follow the state of the parent event,
 	 * not its attr.disabled bit.  We hold the parent's mutex,
 	 * so we won't race with perf_event_{en, dis}able_family.
 	 */
 	if (parent_state >= PERF_EVENT_STATE_INACTIVE)
 		child_event->state = PERF_EVENT_STATE_INACTIVE;
 	else
 		child_event->state = PERF_EVENT_STATE_OFF;

 	if (parent_event->attr.freq) {
 		u64 sample_period = parent_event->hw.sample_period;
 		struct hw_perf_event *hwc = &child_event->hw;

 		hwc->sample_period = sample_period;
 		hwc->last_period   = sample_period;

 		local64_set(&hwc->period_left, sample_period);
 	}

 	child_event->overflow_handler = parent_event->overflow_handler;
 	child_event->overflow_handler_context
 		= parent_event->overflow_handler_context;

 	/*
 	 * Precalculate sample_data sizes
 	 */
 	perf_event__header_size(child_event);
 	perf_event__id_header_size(child_event);

 	/*
 	 * Link it up in the child's context:
 	 */
 	raw_spin_lock_irqsave(&child_ctx->lock, flags);
 	add_event_to_ctx(child_event, child_ctx);
 	child_event->attach_state |= PERF_ATTACH_CHILD;
 	raw_spin_unlock_irqrestore(&child_ctx->lock, flags);

 	/*
 	 * Link this into the parent event's child list
 	 */
 	list_add_tail(&child_event->child_list, &parent_event->child_list);
 	mutex_unlock(&parent_event->child_mutex);

 	return child_event;
 }



